1	@import "tailwindcss";
2	
3	@theme {
4	  --color-brand-50: #f2f0ff;
5	  --color-brand-100: #e4e0ff;
6	  --color-brand-200: #c9c2ff;
7	  --color-brand-300: #a89aff;
8	  --color-brand-400: #8a70fb;
9	  --color-brand-500: #6f47f5;
10	  --color-brand-600: #5f2ee8;
11	  --color-brand-700: #5124c4;
12	  --color-brand-800: #421fa0;
13	  --color-brand-900: #371d7f;
14	
15	  --color-navy-950: #060a14;
16	  --color-navy-900: #0a101f;
17	  --color-navy-850: #0d1526;
18	  --color-navy-800: #111a30;
19	  --color-navy-700: #1a2540;
20	  --color-navy-600: #253354;
21	
22	  --color-accent-blue: #3b82f6;
23	  --color-accent-cyan: #22d3ee;
24	
25	  --animate-fade-up: fade-up 0.4s ease-out both;
26	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
27	
28	  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
29	     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
30	     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
31	  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
32	  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
33	
34	  @keyframes price-pop {
35	    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
36	    to { opacity: 1; transform: translateY(0); filter: blur(0); }
37	  }
38	  @keyframes panel-in {
39	    from { opacity: 0; transform: translateY(12px) scale(0.994); }
40	    to { opacity: 1; transform: translateY(0) scale(1); }
41	  }
42	
43	  /* Showcase mock-screen animations (marketing product pages). All are opt-in
44	     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
45	     resting state (bars full, lines visible) with no motion. */
46	  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
47	  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
48	  --animate-eq: eq 1.7s ease-in-out infinite;
49	  --animate-blink: blink 1.1s steps(1) infinite;
50	  --animate-sweep: sweep 3.4s ease-in-out infinite;
51	  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
52	
53	  @keyframes fade-up {
54	    from { opacity: 0; transform: translateY(8px); }
55	    to { opacity: 1; transform: translateY(0); }
56	  }
57	  @keyframes pulse-dot {
58	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
59	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
60	  }
61	  /* One-shot bar grow (origin at the base). Resting state = full. */
62	  @keyframes grow-up {
63	    from { transform: scaleY(0.06); }
64	    to { transform: scaleY(1); }
65	  }
66	  /* One-shot progress/usage fill. Resting state = full width. */
67	  @keyframes grow-x {
68	    from { transform: scaleX(0); }
69	    to { transform: scaleX(1); }
70	  }
71	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
72	  @keyframes eq {
73	    0%, 100% { transform: scaleY(0.35); }
74	    50% { transform: scaleY(1); }
75	  }
76	  /* Terminal cursor blink. Resting state = visible. */
77	  @keyframes blink {
78	    0%, 49% { opacity: 1; }
79	    50%, 100% { opacity: 0; }
80	  }
81	  /* Soft light sweep across a chart/highlight. */
82	  @keyframes sweep {
83	    0% { transform: translateX(-120%); opacity: 0; }
84	    40%, 60% { opacity: 0.7; }
85	    100% { transform: translateX(320%); opacity: 0; }
86	  }
87	  /* Staggered line/row reveal. Resting state = visible. */
88	  @keyframes line-in {
89	    from { opacity: 0; transform: translateY(6px); }
90	    to { opacity: 1; transform: translateY(0); }
91	  }
92	}
