94	body {
95	  @apply bg-navy-950 text-slate-100 antialiased;
96	  background-image:
97	    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
98	    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
99	  background-attachment: fixed;
100	}
101	
102	::-webkit-scrollbar { width: 10px; height: 10px; }
103	::-webkit-scrollbar-track { background: transparent; }
104	::-webkit-scrollbar-thumb { background: #253354; border-radius: 8px; border: 2px solid #060a14; }
105	::-webkit-scrollbar-thumb:hover { background: #34456e; }
106	
107	@layer components {
108	  /* Surfaces */
109	  .card {
110	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
111	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
112	  }
113	  .card-hover {
114	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
115	  }
116	  .glass {
117	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
118	  }
119	  .glow-brand {
120	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
121	  }
122	
123	  /* Typography */
124	  .grad-text {
125	    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
126	  }
127	  .page-title {
128	    @apply text-2xl font-bold tracking-tight;
129	  }
130	  .section-label {
131	    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
132	  }
133	
134	  /* Buttons */
135	  .btn-primary,
136	  .btn-secondary,
137	  .btn-danger,
138	  .btn-ghost {
139	    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
140	  }
141	  .btn-primary {
142	    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
143	    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
144	  }
145	  .btn-secondary {
146	    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
147	  }
148	  .btn-danger {
149	    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
150	  }
151	  .btn-ghost {
152	    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
153	  }
154	
155	  /* Forms */
156	  .input {
157	    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
158	  }
159	  .label {
160	    @apply mb-1.5 block text-xs font-medium uppercase tracking-wide text-slate-400;
161	  }
162	
163	  /* Nav */
164	  .nav-item {
165	    @apply flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white;
166	  }
167	  .nav-item-active {
168	    @apply bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white;
169	    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
170	  }
171	
172	  /* Tables */
173	  .table-shell {
174	    @apply w-full text-sm;
175	  }
176	  .table-shell thead th {
177	    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
178	  }
179	  .table-shell tbody tr {
180	    @apply border-t border-white/[0.05] transition-colors hover:bg-white/[0.02];
181	  }
182	  .table-shell tbody td {
183	    @apply px-4 py-3;
184	  }
185	
186	  /* Misc */
187	  .kbd {
188	    @apply rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[11px] text-slate-400;
189	  }
190	  .divider {
191	    @apply my-4 border-t border-white/[0.06];
192	  }
193	  .skeleton {
194	    @apply animate-pulse rounded-lg bg-white/[0.06];
195	  }
196	
197	  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
198	     Shared primitives so every page reads as one designed site. The Section
199	     component alternates these background "tones" to give the long pages rhythm
200	     instead of a flat stack. Colors/animations are the existing brand system. */
201	
202	  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
203	  .eyebrow {
204	    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
205	  }
206	  .eyebrow-pill {
207	    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
208	  }
209	
210	  /* Section background tones for alternating rhythm. "panel" is a hair lighter
211	     than the page with hairline separators; "deep" recedes. Replaces one-off
212	     inline gradients scattered across pages. */
213	  .tone-panel {
214	    @apply border-y border-white/[0.05] bg-navy-900/40;
215	  }
216	  .tone-deep {
217	    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
218	  }
219	
220	  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
221	     text automatically. Default = the dark theme's light text. */
222	  :root {
223	    --fg: #ffffff;
224	    --fg-muted: #94a3b8; /* slate-400 */
225	  }
226	
227	  /* "light" tone — a rare, deliberate light band to break up the dark theme and
228	     divide long pages (used sparingly, ~one per page). Flips the foreground
229	     tokens to dark and restyles surfaces/buttons inside so everything stays
230	     legible without touching each call site. */
231	  .tone-light {
232	    @apply border-y border-slate-200/70 text-slate-700;
233	    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
234	    --fg: #0f172a;       /* slate-900 */
235	    --fg-muted: #475569; /* slate-600 */
236	  }
237	  .tone-light .card {
238	    @apply border-slate-200 bg-white text-slate-700;
239	    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
240	  }
241	  .tone-light .card-hover:hover {
242	    @apply border-brand-500/40 bg-white;
243	  }
244	  .tone-light .glass {
245	    @apply border-slate-200 bg-white/70;
246	  }
247	  .tone-light .section-label {
248	    @apply text-slate-500;
249	  }
250	  .tone-light .btn-secondary {
251	    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
252	  }
253	  .tone-light .btn-ghost {
254	    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
255	  }
256	
257	  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
258	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
259	  .hero-aura {
260	    background-image:
261	      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
262	      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
263	  }
264	
265	  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
266	  .lift {
267	    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
268	    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
269	  }
270	
271	  /* Consistent max-width content rail. */
272	  .rail {
273	    @apply mx-auto max-w-6xl px-5 sm:px-6;
274	  }
275	
276	  /* Top-nav dropdown trigger button. */
277	  .nav-trigger {
